/* tmain.c -- the C test runner.
 *
 *   trunner              run everything
 *   trunner --list       print every test (name, description), run nothing
 *   trunner --fam <fam>  run (or list) one family
 *
 * One line per test, a summary, exit 1 when anything failed. The cases are
 * generated by the Makefile from the TH_REG lines (see tharns.h). */

#include <stdlib.h>
#include "tharns.h"

int  th_pass, th_fail, th_ok;
char th_msg[160];

static char cur_name[16];
static char cur_desc[96];
static FILE *cap_old;
static FILE *cap_tmp;

int th_pick(const th_sel_t *s, const char *fam, int num, const char *desc, const char *fn)
{
    (void)num;
    if (s->fam && strcmp(s->fam, fam) != 0) return 0;
    snprintf(cur_name, sizeof cur_name, "%s", fn);
    snprintf(cur_desc, sizeof cur_desc, "%s", desc);
    if (s->list) {
        printf("%-6s %s\n", cur_name, cur_desc);
        return 0;
    }
    th_ok = 0;
    th_msg[0] = '\0';
    return 1;
}

void th_done(void)
{
    if (th_ok && th_msg[0] == '\0') {
        th_pass++;
        printf("PASS %-6s %s\n", cur_name, cur_desc);
        return;
    }
    th_fail++;
    printf("FAIL %-6s %s\n", cur_name, cur_desc);
    printf("     %s\n", th_msg[0] ? th_msg : "returned without reaching PASS()");
}

void th_cap_on(void)
{
    cap_old = stderr;
    cap_tmp = tmpfile();
    if (cap_tmp) stderr = cap_tmp;
}

size_t th_cap_off(char *buf, size_t sz)
{
    size_t n = 0;

    if (!cap_tmp) { buf[0] = '\0'; return 0; }
    fflush(cap_tmp);
    rewind(cap_tmp);
    if (sz > 1) n = fread(buf, 1, sz - 1, cap_tmp);
    buf[n] = '\0';
    stderr = cap_old;
    fclose(cap_tmp);
    cap_tmp = NULL;
    return n;
}

#include "tcases.h"

int main(int argc, char **argv)
{
    th_sel_t sel;
    int i;

    sel.list = 0;
    sel.fam = NULL;
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--list") == 0) sel.list = 1;
        else if (strcmp(argv[i], "--fam") == 0 && i + 1 < argc) sel.fam = argv[++i];
        else {
            fprintf(stderr, "usage: trunner [--list] [--fam <fam>]\n");
            return 2;
        }
    }
    th_all(&sel);
    if (sel.list) return 0;
    printf("%d passed, %d failed\n", th_pass, th_fail);
    if (th_pass + th_fail == 0) {
        printf("no tests ran%s%s\n", sel.fam ? " for family " : "", sel.fam ? sel.fam : "");
        return 1;
    }
    return th_fail != 0;
}
